INSERT INTO `diseases` (`id`, `name`, `cause`, `symptoms`, `treatment`, `image`, `category`, `created_at`) VALUES
(1, 'Leaf Yellowing (Chlorosis)', 'Iron deficiency or poor drainage.', 'New leaves pale, veins may stay green.', 'Test soil, apply chelated iron or correct pH.', 'leaf_yellowing.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(2, 'Bacterial Wilt', 'Soil-borne bacteria (e.g., Ralstonia).', 'Sudden wilting, stem browning.', 'Remove infected plants; improve crop rotation.', 'bacterial_wilt.jpeg', 'Bacterial', '2025-12-11 12:41:30'),
(3, 'Aphid Infestation', 'Sap-feeding insects.', 'Sticky honeydew, curled leaves.', 'Spray insecticidal soap or neem oil; encourage predators.', 'aphid_infestation.jpeg', 'Insect', '2025-12-11 12:41:30'),
(4, 'Root Rot (Phytophthora)', 'Waterlogged soil & fungal pathogen.', 'Soft brown roots, stunting, wilting.', 'Improve drainage, repot into fresh, well-drained mix.', 'root_rot.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(5, 'Early Blight', 'Fungal infection (Alternaria).', 'Circular brown lesions on leaves and stems.', 'Remove infected foliage; apply appropriate fungicide.', 'early_blight.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(6, 'Rust', 'Rust fungi (Pucciniales).', 'Orange/brown pustules underside of leaves.', 'Remove affected leaves; fungicide, increase air flow.', 'rust.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(7, 'Leaf Spot', 'Various fungal or bacterial pathogens.', 'Brown/black spots on foliage.', 'Sanitation; fungicide or bactericide as appropriate.', 'leaf_spot.jpeg', 'Fungal/Bacterial', '2025-12-11 12:41:30'),
(8, 'Downy Mildew', 'Oomycetes in humid conditions.', 'Pale patches, gray/white down on underside.', 'Reduce humidity, apply copper fungicide.', 'downy_mildew.jpeg', 'Oomycete', '2025-12-11 12:41:30'),
(9, 'Spider Mites', 'Tiny mite pests, dry conditions.', 'Fine webbing, stippled leaves.', 'Increase humidity, use miticide or neem oil.', 'spider_mites.jpeg', 'Pest', '2025-12-11 12:41:30'),
(10, 'Powdery Mildew', 'Powdery fungi on foliage.', 'White powdery coating on leaves/stems.', 'Prune for airflow; use sulfur or potassium bicarbonate spray.', 'powdery_mildew.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(11, 'Mosaic Virus', 'Viral pathogens spread by insects.', 'Mottled or mosaic leaf pattern, stunting.', 'Remove infected plants; control insect vectors.', 'mosaic_virus.jpeg', 'Viral', '2025-12-11 12:41:30'),
(12, 'Scale Insects', 'Sap-sucking scale pests.', 'Bumps on stems/leaves; honeydew and sooty mold.', 'Scrape off scales; use horticultural oil.', 'scale_insects.jpeg', 'Pest', '2025-12-11 12:41:30'),
(13, 'Mealybugs', 'Soft-bodied sap feeders.', 'White cottony masses; plant decline.', 'Remove by hand or with alcohol swab; insecticidal soap.', 'mealybugs.jpeg', 'Pest', '2025-12-11 12:41:30'),
(14, 'Thrips', 'Tiny piercing-sucking insects.', 'Silvering of leaves, distorted flowers.', 'Sticky traps, insecticidal soap or spinosad.', 'thrips.jpeg', 'Pest', '2025-12-11 12:41:30'),
(15, 'Whitefly Infestation', 'Small flying sap-feeders.', 'Yellowing leaves, sticky honeydew.', 'Yellow sticky traps; insecticidal soap.', 'whitefly_infestation.jpeg', 'Pest', '2025-12-11 12:41:30'),
(16, 'Botrytis (Gray Mold)', 'Botrytis cinerea fungus in damp conditions.', 'Gray fuzzy mold on flowers/leaves.', 'Remove affected tissue, improve airflow, fungicide.', 'botrytis_gray_mold.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(17, 'Canker', 'Fungal or bacterial stem infection.', 'Sunken, dead areas on bark/stems.', 'Prune out infected wood; disinfect tools.', 'canker.jpeg', 'Fungal/Bacterial', '2025-12-11 12:41:30'),
(18, 'Crown Gall', 'Agrobacterium tumefaciens bacteria.', 'Tumor-like galls at crown or roots.', 'Remove and destroy infected plants; avoid contaminated soil.', 'crown_gall.jpeg', 'Bacterial', '2025-12-11 12:41:30'),
(19, 'Verticillium Wilt', 'Soil fungus (Verticillium).', 'Yellowing, wilting, vascular browning.', 'Remove infected plants; rotate crops.', 'verticillium_wilt.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(20, 'Fusarium Wilt', 'Fusarium oxysporum fungus.', 'One-sided wilting, brown vascular tissues.', 'Use resistant varieties; soil solarization where possible.', 'fusarium_wilt.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(21, 'Brown Patch (Turf)', 'Fungal disease in warm, wet weather.', 'Circular brown patches in turf.', 'Improve drainage; fungicide and cultural control.', 'brown_patch.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(22, 'Black Spot (Rose)', 'Diplocarpon rosae fungus.', 'Black circular spots on rose leaves.', 'Remove leaves; use fungicide sprays.', 'black_spot.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(23, 'Blossom End Rot', 'Calcium deficiency and irregular watering.', 'Dark sunken area at fruit bottom.', 'Consistent watering; supply calcium if needed.', 'blossom_end_rot.jpeg', 'Physiological', '2025-12-11 12:41:30'),
(24, 'Sunscald / Sunburn', 'Sudden exposure to intense sun/heat.', 'Bleached or brown patches on leaves/fruit.', 'Provide shade; gradual acclimation.', 'sunscald_sunburn.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(25, 'Leaf Curl', 'Fungal pathogens or environmental stress.', 'Twisted, puckered leaves.', 'Prune affected parts; fungicide or cultural fixes.', 'leaf_curl.jpeg', 'Fungal/Abiotic', '2025-12-11 12:41:30'),
(26, 'Leaf Scorch', 'High heat, drought or root damage.', 'Margins turn brown and crispy.', 'Improve watering and mulch roots.', 'leaf_scorch.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(27, 'Iron Chlorosis', 'Iron unavailable due to high pH.', 'Yellow leaves with green veins.', 'Lower pH or apply iron chelate.', 'iron_chlorosis.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(28, 'Root-knot Nematode', 'Soil nematodes attacking roots.', 'Galls on roots, poor vigor.', 'Solarize soil; use resistant varieties.', 'root_knot_nematode.jpeg', 'Nematode', '2025-12-11 12:41:30'),
(29, 'Leafminer Damage', 'Larvae tunneling inside leaves.', 'White squiggly tunnels in leaves.', 'Remove affected leaves; use systemic insecticide if severe.', 'leafminer_damage.jpeg', 'Pest', '2025-12-11 12:41:30'),
(30, 'Caterpillar Feeding', 'Caterpillar larvae chewing foliage.', 'Ragged holes, defoliation.', 'Handpick; use Bacillus thuringiensis (Bt) if needed.', 'caterpillar_feeding.jpeg', 'Pest', '2025-12-11 12:41:30'),
(31, 'Slugs & Snails', 'Mollusc pests in moist conditions.', 'Irregular holes, slime trails at night.', 'Handpick at night; traps or iron phosphate baits.', 'slugs_and_snails.jpeg', 'Pest', '2025-12-11 12:41:30'),
(32, 'Borer Infestation', 'Beetle/larvae tunneling in wood.', 'Sawdust, dieback, holes in bark.', 'Remove infected branches; control adults with traps.', 'borer_infestation.jpeg', 'Pest', '2025-12-11 12:41:30'),
(33, 'Weevil Damage', 'Root-and-leaf feeding beetles.', 'Notched leaf margins, root damage.', 'Apply appropriate insecticide; remove affected plants.', 'weevil_damage.jpeg', 'Pest', '2025-12-11 12:41:30'),
(34, 'Tomato Yellow Leaf Curl Virus', 'Whitefly-transmitted virus.', 'Leaf curling, yellowing, reduced yield.', 'Remove infected plants; control whiteflies.', 'tomato_yellow_leaf_curl_virus.jpeg', 'Viral', '2025-12-11 12:41:30'),
(35, 'Cercospora Leaf Spot', 'Cercospora fungus.', 'Small circular spots with tan centers.', 'Fungicide and sanitation.', 'cercospora_leaf_spot.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(36, 'Clubroot', 'Plasmodiophora brassicae in brassicas.', 'Swollen distorted roots, wilting.', 'Raise soil pH, rotate crops.', 'clubroot.jpeg', 'Protist', '2025-12-11 12:41:30'),
(37, 'Damping Off', 'Soil-borne fungi attacking seedlings.', 'Seedlings collapse at soil line.', 'Use sterile medium and proper moisture; fungicide seed treatment.', 'damping_off.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(38, 'Bacterial Leaf Spot', 'Bacterial pathogens (e.g., Xanthomonas).', 'Water-soaked spots that turn brown.', 'Copper sprays; remove infected tissue.', 'bacterial_leaf_spot.jpeg', 'Bacterial', '2025-12-11 12:41:30'),
(39, 'Fire Blight', 'Erwinia amylovora bacteria on pome fruits.', 'Blackened shoots, oozing cankers.', 'Prune infected wood; disinfect tools between cuts.', 'fire_blight.jpeg', 'Bacterial', '2025-12-11 12:41:30'),
(40, 'Needle Cast', 'Fungal infection of conifers.', 'Browning/losing needles prematurely.', 'Remove infected needles; fungicide on susceptible species.', 'needle_cast.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(41, 'Tip Blight', 'Fungal pathogens on shoots.', 'Dead shoot tips and dieback.', 'Prune back to healthy tissue; fungicide if necessary.', 'tip_blight.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(42, 'Scab', 'Streptomyces or fungi depending on crop.', 'Rough lesions on tubers or fruit.', 'Crop rotation; resistant varieties.', 'apple_scab.jpeg', 'Fungal/Bacterial', '2025-12-11 12:41:30'),
(43, 'Leaf Blister', 'Fungal infection (e.g., Taphrina).', 'Blistered, puckered leaves.', 'Remove affected leaves; fungicide if required.', 'leaf_blister.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(44, 'Sooty Mold', 'Fungal growth on honeydew from pests.', 'Black soot-like coating on leaves.', 'Control sap-sucking insects; wash surfaces.', 'sooty_mold.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(45, 'Phytophthora Root Rot', 'Water mold pathogen in wet soils.', 'Collapsed seedlings, root decay.', 'Improve drainage; fungicide drenches for high-value plants.', 'phytophthora_root_rot.jpeg', 'Oomycete', '2025-12-11 12:41:30'),
(46, 'Powdery Scab', 'Spongospora subterranea on potatoes.', 'Pustules on tubers.', 'Use certified seed; rotate fields.', 'powdery_scab.jpeg', 'Fungal-like', '2025-12-11 12:41:30'),
(47, 'Yellow Mosaic', 'Viral infection transmitted by aphids.', 'Yellow mosaic patterns on leaves.', 'Remove inoculum; control vectors.', 'yellow_mosaic.jpeg', 'Viral', '2025-12-11 12:41:30'),
(48, 'Herbicide Injury', 'Drift or residual herbicide exposure.', 'Twisted growth, chlorosis, necrosis.', 'Avoid exposure; flush soil if possible; replace plants if severe.', 'herbicide_injury.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(49, 'Drought / Water Stress', 'Inadequate soil moisture.', 'Wilting, leaf curling, browning.', 'Deep watering, mulching, choose drought-tolerant species.', 'drought_water_stress.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(50, 'Frost Damage', 'Low temperature exposure.', 'Blackened, water-soaked tissue.', 'Protect with covers; prune dead tissue after thaw.', 'frost_damage.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(51, 'Salt / Salinity Damage', 'Salt buildup from irrigation or roads.', 'Leaf margin burn, stunted growth.', 'Leach soil with fresh water; improve drainage.', 'salt_salinity_damage.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(52, 'Heat Stress', 'Prolonged high temperatures.', 'Leaf drop, scorched foliage.', 'Shade cloth, mulching, extra irrigation.', 'heat_stress.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(53, 'Root Damage (Mechanical)', 'Construction, compaction or transplant injury.', 'Poor vigor, wilting despite adequate water.', 'Reduce compaction; prune broken roots; improve soil health.', 'root_damage_mechanical.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(54, 'Nitrogen Deficiency', 'Low available nitrogen.', 'Uniform yellowing starting with older leaves.', 'Apply balanced nitrogen fertilizer or compost.', 'nitrogen_deficiency.jpeg', 'Nutrient', '2025-12-11 12:41:30'),
(55, 'Potassium Deficiency', 'Low soil potassium.', 'Marginal scorch and weak stems.', 'Potash application; wood ash (limited) or K fertilizer.', 'potassium_deficiency.jpeg', 'Nutrient', '2025-12-11 12:41:30'),
(56, 'Magnesium Deficiency', 'Low soil magnesium.', 'Interveinal yellowing on older leaves.', 'Epsom salts foliar feed or soil application.', 'magnesium_deficiency.jpeg', 'Nutrient', '2025-12-11 12:41:30'),
(57, 'Zinc Deficiency', 'Zinc-poor soils or high pH.', 'Small leaves, shortened internodes.', 'Zinc sulfate or chelated zinc application.', 'zinc_deficiency.jpeg', 'Nutrient', '2025-12-11 12:41:30'),
(58, 'Boron Deficiency', 'Low boron availability.', 'Growing points dieback; hollow stems/fruit.', 'Apply borate carefully (narrow range of safety).', 'boron_deficiency.jpeg', 'Nutrient', '2025-12-11 12:41:30'),
(59, 'Calcium Deficiency', 'Poor uptake due to irregular watering.', 'Blossom end rot, distorted new growth.', 'Even watering; calcium amendments if needed.', 'calcium_deficiency.jpeg', 'Nutrient', '2025-12-11 12:41:30'),
(60, 'Shot Hole Borer / Wood Borers', 'Beetles boring into stems/trunks.', 'Holes, frass, branch dieback.', 'Remove and destroy infested wood; insecticide for adults.', 'shot_hole_borer_wood_borers.jpeg', 'Pest', '2025-12-11 12:41:30'),
(61, 'Downy Mildew (Cucurbits)', 'Specialized downy mildew pathogens.', 'Angular yellow patches on leaves.', 'Use resistant cultivars; fungicide sprays.', 'downy_mildew_cucurbits.jpeg', 'Oomycete', '2025-12-11 12:41:30'),
(62, 'Late Blight', 'Phytophthora infestans on potato/tomato.', 'Water-soaked lesions; rapid collapse.', 'Destroy infected plants; regular fungicide protection.', 'late_blight.jpeg', 'Oomycete', '2025-12-11 12:41:30'),
(63, 'Early Blight (Tomato)', 'Alternaria solani.', 'Target-like spots on leaves; defoliation.', 'Mulch, remove debris; fungicides if necessary.', 'early_blight_tomato.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(64, 'Powdery Mildew (Grapes)', 'Erysiphe necator fungus.', 'White dusty coating on leaves and fruit.', 'Sulfur or specific fungicides; canopy management.', 'powdery_mildew_grapes.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(65, 'Pear Rust', 'Gymnosporangium fungi.', 'Bright orange spots on leaves; deformities.', 'Remove alternate juniper hosts; fungicide.', 'pear_rust.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(66, 'Peacock Spot (Olive)', 'Fungal infection on olive leaves.', 'Dark round spots with yellow halo.', 'Copper sprays and sanitation.', 'peacock_spot_olive.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(67, 'Black Sigatoka (Banana)', 'Mycosphaerella fijiensis.', 'Dark streaks and leaf necrosis.', 'Regular fungicide applications; resistant clones.', 'black_sigatoka_banana.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(68, 'Apple Scab', 'Venturia inaequalis fungus.', 'Olive-green spots on leaves and fruit.', 'Scab-resistant varieties; fungicides in spring.', 'apple_scab.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(69, 'Vascular Wilt (General)', 'Several fungi blocking xylem.', 'Wilting, brown streaks in wood.', 'Remove infected material; use resistant species where possible.', 'vascular_wilt_general.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(70, 'Anthracnose', 'Colletotrichum and similar fungi.', 'Dark sunken lesions on leaves, stems and fruit.', 'Sanitation; fungicide and improved airflow.', 'anthracnose.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(71, 'Botrytis on Flowers', 'Botrytis in humid environments.', 'Gray mold on blooms and buds.', 'Remove affected blooms and improve ventilation.', 'botrytis_on_flowers.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(72, 'Sclerotinia (White Mold)', 'Sclerotinia sclerotiorum.', 'Watery soft rot, white mycelium, black sclerotia.', 'Remove infected tissue; fungicide; crop rotation.', 'sclerotinia_white_mold.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(73, 'Crown Rot', 'Fungal pathogens at crown area.', 'Crown decay, collapse of plant.', 'Improve soil drainage; avoid injuring crown.', 'crown_rot.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(74, 'Phoma Leaf Spot', 'Phoma species fungi.', 'Small dark lesions often grouped.', 'Remove debris; fungicide if outbreak occurs.', 'phoma_leaf_spot.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(75, 'Banana Bunchy Top Virus', 'Viral disease transmitted by aphids.', 'Stunted growth; bunching of leaves.', 'Remove infected plants; control vectors.', 'banana_bunchy_top_virus.jpeg', 'Viral', '2025-12-11 12:41:30'),
(76, 'Brown Blotch', 'Bacterial or fungal agents on foliage/fruit.', 'Brown spots that may coalesce.', 'Improve spray coverage; remove infected parts.', 'brown_blotch.jpeg', 'Bacterial/Fungal', '2025-12-11 12:41:30'),
(77, 'Vine Weevil (Adult/Grub Damage)', 'Weevil larvae feeding on roots.', 'Wilting, plant collapse; adult notches on leaves.', 'Apply nematodes for larvae; pick adults at night.', 'vine_weevil_adult_grub_damage.jpeg', 'Pest', '2025-12-11 12:41:30'),
(78, 'Armored Scale Infestation', 'Armored scale insects attaching to bark/leaves.', 'Tiny hard bumps; yellowing leaves.', 'Horticultural oil during dormant season; manual removal.', 'armored_scale_infestation.jpeg', 'Pest', '2025-12-11 12:41:30'),
(79, 'Vegetable Downy Mildew', 'Oomycetes on vegetable leaves.', 'Pale angular spots on topside; downy growth underside.', 'Use resistant varieties; fungicide program.', 'vegetable_downy_mildew.jpeg', 'Oomycete', '2025-12-11 12:41:30'),
(80, 'Fruit Brown Rot', 'Monilinia and similar fungi.', 'Brown rotting of fruit; mummification.', 'Remove mummies; apply fungicides at bloom and pre-harvest.', 'fruit_brown_rot.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(81, 'Leaf Blotch (General)', 'Various fungi causing blotches.', 'Irregular blotches on leaves.', 'Sanitation; fungicide if damaging.', 'leaf_blotch_general.jpeg', 'Fungal', '2025-12-11 12:41:30'),
(82, 'Lesion Nematode Damage', 'Pratylenchus species causing root lesions.', 'Root lesions, poor uptake, stunting.', 'Rotate crops; soil health improvements.', 'lesion_nematode_damage.jpeg', 'Nematode', '2025-12-11 12:41:30'),
(83, 'Orchid Viruses (General)', 'Multiple viruses, often sap-transmitted.', 'Mottling, streaks, poor growth.', 'Rogue infected plants; sterilize tools.', 'orchid_viruses_general.jpeg', 'Viral', '2025-12-11 12:41:30'),
(84, 'Stem Borer / Cane Borer', 'Larvae boring into canes/stems.', 'Cane dieback, sawdust at entry holes.', 'Prune out infested canes; destroy them.', 'stem_borer_cane_borer.jpeg', 'Pest', '2025-12-11 12:41:30'),
(85, 'Bacterial Soft Rot', 'Erwinia and other bacteria on fleshy crops.', 'Soft watery decay with foul smell.', 'Improve storage/handling; remove infected produce.', 'bacterial_soft_rot.jpeg', 'Bacterial', '2025-12-11 12:41:30'),
(86, 'Mosaic on Peppers/Beans', 'Viruses transmitted by aphids or thrips.', 'Mosaic patterns, reduced vigor.', 'Remove infected, use reflective mulches and insect control.', 'mosaic_on_peppers_beans.jpeg', 'Viral', '2025-12-11 12:41:30'),
(87, 'Micronutrient Toxicity (Manganese)', 'Excess in soil or low pH.', 'Dark spots, necrosis, chlorosis in patterns.', 'Raise pH and avoid over-application of fertilizers.', 'micronutrient_toxicity_manganese.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(88, 'Competition / Weed Pressure', 'Weeds stealing resources.', 'Stunted crop growth, reduced yields.', 'Mulch, weed control, timely cultivation.', 'competition_weed_pressure.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(89, 'Algal Leaf Spot', 'Algae growing on leaves in wet conditions.', 'Greenish or oval spots on foliage.', 'Reduce leaf wetness; copper sprays if needed.', 'algal_leaf_spot.jpeg', 'Biotic', '2025-12-11 12:41:30'),
(90, 'Serpentine Leafminer', 'Fly larvae tunneling between leaf surfaces.', 'Thin winding trails in leaves.', 'Remove affected leaves; use row covers or systemic insecticide.', 'serpentine_leafminer.jpeg', 'Pest', '2025-12-11 12:41:30'),
(91, 'Lightning / Electrical Damage', 'Electrical strikes or contact.', 'Split bark, sudden dieback.', 'Remove hazardous branches; consult arborist.', 'lightning_electrical_damage.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(92, 'Bird & Wildlife Damage', 'Birds and animals feeding on fruit/leaves.', 'Pecked fruit, torn leaves.', 'Netting, scare devices, timely harvest.', 'bird_wildlife_damage.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(93, 'Manganese Deficiency', 'Low manganese availability.', 'Interveinal chlorosis similar to iron but on younger leaves.', 'Manganese chelate foliar feed or soil application.', 'manganese_deficiency.jpeg', 'Nutrient', '2025-12-11 12:41:30'),
(94, 'Poor Soil Structure / Compaction', 'Heavy foot traffic or poor management.', 'Stunted roots, water pooling.', 'Incorporate organic matter; aerate or loosen soil.', 'poor_soil_structure_compaction.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(95, 'Overwatering', 'Excessive irrigation or poor drainage.', 'Yellowing leaves, root decline, fungal issues.', 'Reduce watering; improve drainage and pot mix.', 'overwatering.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(96, 'Underwatering', 'Insufficient moisture.', 'Wilting, dry brown leaf tips.', 'Deep, regular watering and mulching to retain moisture.', 'underwatering.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(97, 'Fertilizer Burn / Salt Build-Up', 'Excess fertilizer or salts in soil.', 'Leaf margin browning, root damage.', 'Leach salts with ample water; reduce fertilizer rates.', 'fertilizer_burn_salt_build_up.jpeg', 'Abiotic', '2025-12-11 12:41:30'),
(98, 'Tumors / Galls (Various)', 'Bacteria, nematodes or insects.', 'Localized swellings on roots, stems or leaves.', 'Remove affected parts; improve hygiene and rotate crops.', 'tumors_galls_various.jpeg', 'Biotic', '2025-12-11 12:41:30'),
(99, 'Poor Cultural Practices', 'Wrong plant in wrong place, improper pruning or watering.', 'Chronic poor performance and recurring problems.', 'Follow best practices: correct siting, soil prep, pruning and watering.', 'poor_cultural_practices.jpeg', 'Management', '2025-12-11 12:41:30');
